    lines = input_str.strip().split('\n')

    # Parse input
    n = int(lines[0])

    ships = []
    for i in range(n):
        x, y = map(int, lines[1 + i].split())
        ships.append(Points(x, y, is_ship=True, idx=i))

    bases = []
    for i in range(n, 2 * n):
        x, y = map(int, lines[i].split())
        bases.append(Points(x, y, is_ship=False, idx=i - n))

    # Sort by x-coordinate as primary, y-coordinate as secondary
    sorted_ships = sorted(ships, key=lambda p: (p.x, p.y))
    sorted_bases = sorted(bases, key=lambda p: (p.x, p.y))

    # Match in sorted order
    result = []
    for i in range(n):
        result.append(sorted_bases[i].idx + 1)  # 1-indexed

    # Return result as string
    return '\n'.join(map(str, result))

