        # Check if already divisible by some k > 1
        if S > 1:
            # For n=1, we need all boxes divisible by k > 1, means a[0] must have a divisor > 1
            # But we can't move pieces, so it must already be divisible
            for k in range(2, a[0] + 1):
                if a[0] % k == 0:
                    return '0\n'
            return '-1\n'
        return '-1\n'

    # Find all divisors of S
    divisors = set()
    for i in range(2, int(S**0.5) + 1):
        if S % i == 0:
            divisors.add(i)
            divisors.add(S // i)

    min_cost = float('inf')

    # Precompute prefix sums
    prefix = [0] * n
    for i in range(n):
