    # Compute prefix sums
    prefix = [0] * n
    current = 0
    for i in range(n):
        current += a[i]
        prefix[i] = current

    # Function to get cost for a given k
    def get_cost(k):
        cost = 0
        for i in range(n - 1):
            cost += abs(prefix[i] % k)
        return cost

    # Find divisors of S
    divisors = []
    i = 1
    while i * i <= S:
        if S % i == 0:
            if i > 1:
                divisors.append(i)
            if i * i != S and S // i > 1:
