from bisect import bisect_right

def solution(input_data):
    """
    Find the minimum number of operations to sort an array using:
    1. Move element to beginning
    2. Move element to end

    The minimum operations = n - length of longest non-decreasing subsequence
    """
    lines = input_data.strip().split('\n')
    idx = 0

    # Handle empty input
    if not lines:
        return '0'

    try:
        t = int(lines[idx])
        idx += 1
    except ValueError:
        return '0'

    results = []

    for _ in range(t):
        try:
            # Read n
            n_str = lines[idx]
            idx += 1
            if n_str.strip():
                n = int(n_str)
            else:
                break

            # Read array elements
            if idx < len(lines):
                a = list(map(int, lines[idx].split()))
                idx += 1
            else:
                a = []

        except (ValueError, IndexError):
            break

        if n == 0:
            results.append('0')
        else:
            # Find longest non-decreasing subsequence using O(n log n) algorithm
            # tails[i] = smallest ending element of a non-decreasing subsequence of length i+1
            tails = []

            for val in a:
                # bisect_right finds first element >= val for non-decreasing pattern
                pos = bisect_right(tails, val)
                if pos < len(tails):
                    tails[pos] = val
                else:
                    tails.append(val)

            lds_length = len(tails)
            results.append(str(n - lds_length))

    return '\n'.join(results)

