def get_block_length(n):
    """Calculate total length of digits in all numbers from 1 to n."""
    total = 0
    p = 1  # power of 10, gives number of digits
    while p <= n:
        digit_count = min(n, p * 10 - 1) - p + 1
        total += digit_count * p
        p *= 10
    return total


def get_telegram_length(n_blocks):
    """Calculate total length of concatenating blocks 1 through n_blocks."""
    total_len = 0
    for i in range(1, n_blocks + 1):
        total_len += get_block_length(i)
    return total_len


def get_digit_at_block_pos(block, n):
    """Get the digit at position n in block block (which is "123...block")."""
    curr_len = 0
    num = 1
    while num <= block:
        n_digits = len(str(num))
        if curr_len + n_digits >= n:
            s_num = str(num)
            return s_num[n - curr_len - 1]
        curr_len += n_digits
        num += 1
    return None


def find_digit_in_sequence(k):
    """Find the digit at position k in the infinite sequence."""
    block = 1

    while True:
        blen = get_telegram_length(block)
        if k <= blen:
            block_len = get_block_length(block)
            pos = k - 1  # 0-indexed position within this block
            total = 0
            num = 1
            while True:
                l = len(str(num))
                if total + l > pos:
                    return str(num)[pos - total]
                total += l
                num += 1
        else:
            k -= (blen - get_telegram_length(block - 1))
            block += 1


