def check_valid(arr, n):
    """Check if array can be made non-decreasing with at most 1 swap"""
    # Check if already sorted
    if arr == sorted(arr):
        return True

    # Precompute prefix sortedness
    first_bad = -1
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            first_bad = i
            break

    if first_bad == -1:
        return True

    # Precompute suffix sortedness
    last_bad = -1
    for i in range(n - 2, -1, -1):
        if arr[i] > arr[i + 1]:
            last_bad = i
            break

    if last_bad == -1:
        return True

    # Must be a single contiguous bad region
    if first_bad != last_bad:
        return False

    # Try swapping at first_bad
    arr_swapped = arr.copy()
    arr_swapped[first_bad], arr_swapped[first_bad + 1] = arr_swapped[first_bad + 1], arr_swapped[first_bad]

    # Check if swapped version is sorted
    return all(arr_swapped[i] <= arr_swapped[i + 1] for i in range(n - 1))

