import heapq

def solution(input_str):
    lines = input_str.strip().split('\n')

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]

    for i in range(m):
        u, v, w = map(int, lines[1 + i].split())
        adj[u].append((v, w, i + 1))
        adj[v].append((u, w, i + 1))

    start = int(lines[1 + m])

    # Dijkstra's algorithm
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        for v, w, idx in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # Find edges with minimum weight that lie on shortest paths
    total_weight = 0
    tree_edges = []

    for v in range(1, n + 1):
        if v == start:
            continue

        min_w = float('inf')
        min_w_id = -1

        for u, w, idx in adj[v]:
            if dist[u] + w == dist[v]:
                if w < min_w:
                    min_w = w
                    min_w_id = idx

        if min_w_id != -1:
            total_weight += min_w
            tree_edges.append(str(min_w_id))

    result = f"{total_weight}\n{' '.join(tree_edges)} "
    return result

