    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    events = lines[1:]

    # Parse segments (friends visiting between type 1 events)
    segments = []
    current_segment = set()
    for line in events:
        parts = line.split()
        if parts[0] == '1':
            if current_segment:
                segments.append(current_segment)
                current_segment = set()
        else:
            current_segment.add(parts[1])
    if current_segment:
        segments.append(current_segment)

    # Get unique friends sorted for consistent ordering
    unique_friends = sorted(set(parts[1] for line in events if parts[0] == '2'))
    n_unique = len(unique_friends)
    friend_to_idx = {f: i for i, f in enumerate(unique_friends)}

    # Build conflict graph using bit masks
    # conflict_mask[i] has bit j set if friends i and j conflict
    conflict_mask = [0] * n_unique
    for segment in segments:
        if len(segment) >= 2:
            friends_in_seg = [friend_to_idx[f] for f in sorted(segment)]
            for i in range(len(friends_in_seg)):
                for j in range(i + 1, len(friends_in_seg)):
                    conflict_mask[friends_in_seg[i]] |= (1 << friends_in_seg[j])
                    conflict_mask[friends_in_seg[j]] |= (1 << friends_in_seg[i])

    # DFS with memoization to find Maximum Independent Set
    memo = {}

    def dfs(idx, mask):
        state = (idx, mask)
        if state in memo:
            return memo[state]

        # Option 1: Skip friend idx
        best = dfs(idx + 1, mask)

        # Option 2: Take friend idx (if not conflicting with already picked)
        if mask & conflict_mask[idx] == 0:
            best = max(best, 1 + dfs(idx + 1, mask | (1 << idx)))

        memo[state] = best
        return best

    return dfs(0, 0)

