        xs = sorted(d[0] for d in dwarves)
        ys = sorted(d[1] for d in dwarves)
        mx, my = xs[n // 2], ys[n // 2]

        for dx, dy in dwarves:
            # Direct walk distance
            direct = abs(dx - mx) + abs(dy - my)
            if direct <= target_time:
                continue

            # Find best subway option (minimize station->meeting)
            if k == 0:
                return False

            best = float('inf')
            for sx, sy in subways:
                cost = abs(dx - sx) + abs(dy - sy) + abs(sx - mx) + abs(sy - my)
                if cost < best:
                    best = cost

            if best <= target_time:
                continue
            return False
        return True

    low, high = 0, 4000000000
    ans = high

    while low <= high:
        mid = (low + high)
        mid //= 2
        if mid < 0:
            mid = 0
        if verify(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return str(ans) + "\n"

