                    sorted_new = sorted(new_positions)
                    if sorted_new == tuple(range(n - x + 1, n + 1)):
                        min_cost = min(min_cost, cost)
                    else:
                        min_cost = min(min_cost, cost + sub_cost)

        return min_cost if min_cost != float('inf') else 0

    initial_pos = tuple(range(1, x + 1))
    result = dp(initial_pos)
