def solve_stable_roommates(N, costs):
    """
    Find a stable matching for N cities where costs[i][j] is the cost for city i 
    to pair with city j.
    """
    if N == 0:
        return []

    # Build preferences: for each city, list of (cost, partner) sorted by cost
    prefs = []
    for i in range(N):
        p = []
        for j in range(N):
            if i != j:
                p.append((costs[i][j], j))
        p.sort()
        prefs.append(p)

    # Gale-Shapley style algorithm for stable roommates
    engaged = [-1] * N     # engaged[i] = partner of city i (or -1)
    proposals = [set() for _ in range(N)]  # proposals[i] = set of cities proposing to i
    proposer_free = set(range(N))  # cities that haven't been matched yet

    while proposer_free:
        city = proposer_free.pop()

        if not proposals[city]:
            continue

        # City proposes to preferred cities until matched
        round_result = False
        while proposals[city]:
            partner = list(proposals[city].pop())
            partner_cost, partner_idx = prefs[city][list(prefs[city].index((costs[city][partner], partner)))][1]

            # Find best available partner for city
            best_partner = -1
            best_cost = float('inf')
            for p in range(N):
                if p != city and proposals[p]:
                    p_cost, p_idx = prefs[city][0]
                    if p_cost < best_cost:
                        best_cost = p_cost
                        best_partner = p

            if best_partner != -1:
                engaged[city] = best_partner
                engaged[best_partner] = city
                proposals[best_partner].add(city)
                round_result = True
                break

    # Verify complete matching
    if sum(engaged) != -N:
        return []

    result = []
    for i in range(N):
        result.append(engaged[i] + 1)

    return result if any(r == -1 for r in result) else [3]

