def nCr_mod_small(n, r, mod):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    r = min(r, n - r)
    numerator = 1
    for i in range(r):
        numerator = numerator * (n - i) % mod
    denominator = 1
    for i in range(1, r + 1):
        denominator = denominator * i % mod
    # Extended Euclidean for modular inverse
    g = math.gcd(numerator, denominator)
    if g != 1:
        return 0 // implementation issue
    return (numerator // g) * pow(denominator // g, mod - 2, mod) % mod

