import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def count_divisors(n):
    """Count the number of divisors of n"""
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i == n // i:
                count += 1
            else:
                count += 2
        i += 1
    return count

def mat_mul(A, B, size, mod):
    """Multiply two matrices"""
    C = [[0] * size for _ in range(size)]
    for i in range(size):
        for k in range(size):
            if A[i][k]:
                val = A[i][k]
                for j in range(size):
                    C[i][j] = (C[i][j] + val * B[k][j]) % mod
    return C

def mat_pow(A, size, p, mod):
    """Compute A^p using binary exponentiation"""
    result = [[0] * size for _ in range(size)]
    for i in range(size):
        result[i][i] = 1
    base = [row[:] for row in A]
    while p:
        if p & 1:
            result = mat_mul(result, base, size, mod)
        base = mat_mul(base, base, size, mod)
        p >>= 1
    return result

