def can_force_win(a, b, n):
    """Returns: 'win' if current player has winning strategy, 
               'lose' if current player will lose, 
               'draw' if game continues indefinitely"""

    # Current state already at or beyond limit - shouldn't happen
    if a ** b >= n:
        return "lose"

    # Try move 1: add box
    after_box = (a + 1) ** b < n
    if after_box:
        opponent_result = can_force_win(a + 1, b, n)
        if opponent_result == "lose":
            return "win"
        if opponent_result in ("win", "draw"):
            can_box_win = True
        else:
            can_box_win = False
    else:
        # Adding box makes opponent win (they're in losing state)
        can_box_win = False

    # Try move 2: add item
    after_item = a ** (b + 1) < n
    if after_item:
        opponent_result = can_force_win(a, b + 1, n)
        if opponent_result == "lose":
            return "win"
        if opponent_result in ("win", "draw"):
            can_item_win = True
        else:
            can_item_win = False
    else:
        can_item_win = False

    # Winner found
    if after_box and can_box_win:
        return "win"
    if after_item and can_item_win:
        return "win"

    # Check if both moves lead to opponent winning
    if after_box and after_item:
        return "lose"

    # Otherwise check if game can continue indefinitely
    if not after_box and not after_item:
        return "draw"

    return "draw"

