import math

def solution(input_string):
    input_string = input_string.strip()
    lines = input_string.split('\n')

    n, m = map(int, lines[0].split())

    probs = []
    for line in lines[1:]:
        if line.strip():
            row = list(map(int, line.split()))
            probs.append([p / 1000.0 for p in row])

    # Precompute binomial CDFs for efficiency
    def binomial_cdf(i, t, p):
        """P(X <= t) where X ~ Binomial(i, p)"""
        if t >= i:
            return 1.0
        if t < 0:
            return 0.0

        result = 0.0
        probabilities = [1.0] * (i + 1)

        # Calculate binomial coefficients iteratively
        for k in range(1, i + 1):
            if k == 1:
                probabilities[k] = probabilities[0] * i
            else:
                probabilities[k] = probabilities[k-1] * (i - k + 1) // k
                probabilities[k] *= p

        prob_complement = (1 - p) ** i

        current_prob = 1.0  # C(i, 0) * p^0 * (1-p)^i
        for k in range(t + 1):
            if k > 0:
                # C(i, k) = C(i, k-1) * (i - k + 1) / k
                current_prob = current_prob * (i - k + 1) / k
            current_prob *= p
            if k > 0 and k < i:
                # Multiply by (1-p)^(remaining)
                current_prob = current_prob * prob_complement

        # Calculate combined probability using iterative binomial
        term = math.comb(i, 0) * (p ** 0) * ((1 - p) ** i)
        all_probs = {}
        for k in range(i + 1):
            all_probs[k] = math.comb(i, k) * (p ** k) * ((1 - p) ** (i - k))

        for k in range(min(t + 1, i + 1)):
            result += all_probs[k]

        return result

    def expected_contribution(size_idx, t):
        """Calculate expected satisfied for size with t T-shirts"""
        if t <= 0:
            return 0.0

        result = 0.0
        size_probs = [probs[i][size_idx] for i in range(n)]

        # Count non-zero probability indices for this size
        for i in range(n):
            p_i = size_probs[i]
            if p_i == 0:
                continue

            # P(engineer i gets served) = P(fewer than t before them requested this size)
            prob_i_served = binomial_cdf(i - 1, min(t - 1, i - 1), p_i)
            result += p_i * prob_i_served

        return result

    # DP: dp[j][k] = max expected satisfied using exactly k T-shirts from first j sizes
    dp = [[0.0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(n + 1):
            best = 0.0
            # Try allocating t T-shirts to size i (where 0 <= t <= j)
            for t in range(min(j, n) + 1):
                remaining = j - t
                if remaining < 0:
                    continue

                prev_val = dp[i - 1][remaining]
                curr_val = expected_contribution(i - 1, t)
                best = max(best, prev_val + curr_val)

            dp[i][j] = best

    return f"{dp[m][n]:.9f}"

