import math

def solution(input_str):
    l_str, r_str = input_str.strip().split()
    l = int(l_str)
    r = int(r_str)

    # Edge case: no positive integers in range
    if r < 2:
        return "0\n"

    # Sieve up to sqrt(r) to get small primes for trial division
    B = int(math.isqrt(r)) + 1
    is_prime_small = [True] * B
    if B > 0: is_prime_small[0] = False
    if B > 1: is_prime_small[1] = False

    for i in range(2, int(math.isqrt(B)) + 1):
        if is_prime_small[i]:
            for j in range(i * i, B, i):
                is_prime_small[j] = False

    small_primes = [i for i in range(B) if is_prime_small[i]]

    # Helper to check if a number is prime using trial division
    def is_prime(n):
        if n < 2:
            return False
        for p in small_primes:
            if p * p > n:
                break
            if n % p == 0:
                return False
        # If small_primes ran out and no factor found, n could be prime
        # In our range this is unlikely given the bounds
        return True

    # Count numbers in [l, r] that are prime AND (p=2 or p ≡ 1 mod 4)
    count = 0
    for num in range(l, r + 1):
        if num == 2:
            count += 1
        elif num > 1 and num % 4 == 1:
            if is_prime(num):
                count += 1

    return f"{count}\n"

