    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            count = 0
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                count += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            component_sizes.append(count)

    # Check if any component is already lucky
    def is_lucky(num):
        s = str(num)
        return all(c in '47' for c in s)

    # Generate all lucky numbers up to n iteratively
    lucky_numbers = []
    lucky_q = [4, 7]
    while lucky_q:
        num = lucky_q.pop(0)
        if num <= n:
            lucky_numbers.append(num)
            if num * 10 <= n:
                lucky_q.append(num * 10 + 4)
                lucky_q.append(num * 10 + 7)
    lucky_numbers.sort()

    # DP to find minimum number of components to sum up to each lucky number
    INF = 2 * n + 1
    dp = [INF] * (n + 1)
    dp[0] = 0

    for size in component_sizes:
        for i in range(n, size - 1, -1):
            if dp[i - size] != INF:
                dp[i] = min(dp[i], dp[i - size] + 1)

    # Find minimum (dp[lucky] - 1) for all achievable lucky numbers
    ans = INF
    for lucky in lucky_numbers:
        if dp[lucky] != INF:
            ans = min(ans, dp[lucky] - 1)

