    """
    Solution for the maze navigation problem.

    Finds a path from the starting cell to the finish cell, accounting
    for potential button direction swaps.
    """
    from collections import deque

    # Parse input
    lines = input_str.split('\n')
    lines = [line.strip() for line in lines if line.strip()]
    if not lines:
        return ""

    params = lines[0].split()
    n, m = int(params[0]), int(params[1])

    # Build grid from lines 1 to n
    grid = []
    for i in range(1, min(n + 1, len(lines))):
        row = lines[i]
        grid.append(list(row.ljust(m)[:m]))

    # Pad grid if needed
    while len(grid) < n:
        grid.append(['.'] * m)

    # Find finish cell position
    finish = None
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                finish = (r, c)
                break

    if finish is None:
        return ""

    # Try all 4 configurations of direction swaps
    for swapLR, swapUD in [(False, False), (True, False), (False, True), (True, True)]:
        # Map each button to its actual movement direction
        if swapLR and swapUD:
            move_map = {'U': (1, 0), 'D': (-1, 0), 'L': (0, 1), 'R': (0, -1)}
        elif swapLR:
            move_map = {'U': (0, -1), 'D': (0, 1), 'L': (1, 0), 'R': (-1, 0)}
        elif swapUD:
            move_map = {'U': (0, 1), 'D': (0, -1), 'L': (-1, 0), 'R': (1, 0)}
        else:
            # No swaps - normal directions
            move_map = {'U': (0, -1), 'D': (0, 1), 'L': (-1, 0), 'R': (1, 0)}

        # BFS to find shortest path
        start = (0, 0)
        queue = deque([[start]])  # Each element is a list of positions
        visited = {start}
        path_map = {start: []}

        found = False
        while queue and not found:
            path = queue.popleft()[0]
            curr = path[-1]

            if curr == finish:
                found = True
                result = []
                for pos in path:
                    if pos == start:
                        continue
                    prev = None
                    for i, p in enumerate(path):
                        if p == pos:
                            prev = path[i-1]
                            break
                    # Determine button from position change
                    cr, cc = prev
                    pr, pc = pos
                    dr = pr - cr
                    dc = pc - cc

                    for btn in ['U', 'D', 'L', 'R']:
                        move = move_map.get(btn, (0, 0))
                        if move == (dr, dc):
                            result.append(btn)
                            break

                result_str = '\n'.join(result) + '\n'
                return result_str

            curr_r, curr_c = curr
            for btn in ['U', 'D', 'L', 'R']:
                dr, dc = move_map.get(btn, (0, 0))
                nr, nc = curr_r + dr, curr_c + dc

                if 0 <= nr < n and 0 <= nc < m:
                    if grid[nr][nc] != '*' and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        new_path = path + [(nr, nc)]
                        queue.append([new_path])

        if found:
            # Already returned above, but fallback
            return ""

    return ""

