from collections import Counter

def solution(input_str):
    lines = input_str.strip().split('\n')
    shuffled = lines[0]
    reminder = lines[1]

    counts = Counter(shuffled)
    n_len = len(shuffled)

    best_result = None

    for k in range(1, n_len + 1):
        k_str = str(k)
        k_len = len(k_str)

        if k + k_len != n_len:
            continue

        temp = counts.copy()
        valid = True
        for c in k_str:
            if temp.get(c, 0) <= 0:
                valid = False
                break
            temp[c] -= 1

        if not valid:
            continue

        rem_counts = Counter(reminder)
        remaining = Counter()
        for d, c in temp.items():
            remaining[d] = c - rem_counts.get(d, 0)

        if sum(remaining.values()) != k - len(reminder):
            continue

        num_rest_digits = sum(remaining.values())
        sorted_rest = sorted(remaining.values())

        min_n = None

        for pos in range(k - len(reminder) + 1):
            candidate_chars = [''] * k

            left_idx = 0
            for i in range(pos):
                if left_idx < num_rest_digits:
                    candidate_chars[i] = sorted_rest[left_idx]
                    left_idx += 1

            for i in range(pos, pos + len(reminder)):
                candidate_chars[i] = reminder[i - pos]

            right_idx = left_idx
            for i in range(pos + len(reminder), k):
                if right_idx < num_rest_digits:
                    candidate_chars[i] = sorted_rest[right_idx]
                    right_idx += 1

            candidate = ''.join(candidate_chars)

            if k > 1 and candidate[0] == '0':
                continue

            if min_n is None or candidate < min_n:
                min_n = candidate

        if min_n is not None:
            if best_result is None or min_n < best_result:
                best_result = min_n

    return best_result if best_result else ""

import sys

sys.setrecursionlimit(200000)

MOD = 1_000_000_007

def solve(expression):
    pos = [0]
    n = len(expression)

    def peek():
        return expression[pos[0]] if pos[0] < n else ''

    def consume():
        pos[0] += 1

    def skip_ws():
        while pos[0] < n and expression[pos[0]].isspace():
            consume()

    def parse_number():
        start = pos[0]
        while pos[0] < n and expression[pos[0]].isdigit():
            consume()
        if start == pos[0]:
            return ""
        return expression[start:pos[0]]

    def parse_term():
        """Parse: number | l-r | number(expression)"""
        skip_ws()
        if pos[0] >= n:
            return None, 0

        num_str = parse_number()
        if not num_str:
            return None, 0

        n_val = int(num_str)
        num_len = len(num_str)

        # Check for number - number (range)
        if pos[0] < n and peek() == '-':
            consume()
            r_str = parse_number()
            if not r_str:
                return None, 0

            skip_ws()
            l, r = n_val, int(r_str)
            if l > r:
                return None, 0

            # Concatenate numbers from l to r
            acc = l
            total_len = len(str(l))
            for num in range(l + 1, r + 1):
                s = str(num)
                acc = (acc * pow(10, len(s), MOD) + num) % MOD
                total_len += len(s)
            return acc, total_len

        # Check for number(expression)
        elif pos[0] < n and peek() == '(':
            consume()  # consume '('
            e_val, e_len = parse_expression()
            if e_val is None:
                return None, 0

            skip_ws()
            if pos[0] < n and peek() == ')':
                consume()  # consume ')'
            else:
                return None, 0

            # Return n_val copies of expression, concatenated
            result = e_val
            for _ in range(n_val):
                result = (result * pow(10, e_len, MOD) + e_val) % MOD
            total_len = e_len * n_val
            return result, total_len

        # Just a number
        return n_val % MOD, num_len

    def parse_expression():
        """Parse: term | expression + term"""
        left_val, left_len = parse_term()
        if left_val is None:
            return None, 0

        while pos[0] < n and peek() == '+':
            consume()  # consume '+'
            right_val, right_len = parse_term()
            if right_val is None:
                return None, 0

            # Concatenate: left + right
            left_val = (left_val * pow(10, right_len, MOD) + right_val) % MOD
            left_len += right_len

        return left_val, left_len

    result_val, _ = parse_expression()
    return result_val

# For pytest compatibility
def solution(expr_str):
    return solve(expr_str)
